// Build a payment profile per client (recency-weighted, with trend), group open
// invoices by client and attach any NEW reply the client sent since the last run.
const cfg = $('Set Dunning Rules1').first().json;
const invoices = $('Read Open Invoices1').all().map(i => i.json);
const history = $('Read Payment History1').all().map(i => i.json);
const responses = $('Read Client Responses').all().map(i => i.json).filter(r => r['Response ID']);
const mails = $input.all().map(i => i.json).filter(m => m.id);

const DAY = 86400000;
const today = new Date(); today.setHours(0, 0, 0, 0);
const parse = v => { if (!v) return null; const d = new Date(v); if (isNaN(d)) return null; d.setHours(0, 0, 0, 0); return d; };
const iso = d => d.toISOString().slice(0, 10);
const halfLife = Number(cfg.recencyHalfLifeDays) || 180;
const CLOSED = ['paid', 'void', 'cancelled', 'canceled', 'written off'];

// 1. Payment history -> weighted profile per client
const hist = {};
for (const h of history) {
  const id = String(h['Client ID'] || '').trim();
  const due = parse(h['Due Date']), paid = parse(h['Paid Date']);
  if (!id || !due || !paid) continue;
  const late = Math.max(0, Math.round((paid - due) / DAY));
  const age = Math.max(0, (today - due) / DAY);
  (hist[id] = hist[id] || []).push({ due, late, w: Math.pow(0.5, age / halfLife) });
}
const profileOf = id => {
  const list = (hist[id] || []).sort((a, b) => a.due - b.due);
  if (!list.length) return { hasHistory: false, count: 0, lateRate: 0.3, avgLate: 5, maxLate: 0, trend: 0 };
  const wSum = list.reduce((s, x) => s + x.w, 0);
  const lateRate = list.reduce((s, x) => s + (x.late > 0 ? x.w : 0), 0) / wSum;
  const avgLate = list.reduce((s, x) => s + x.late * x.w, 0) / wSum;
  const overall = list.reduce((s, x) => s + x.late, 0) / list.length;
  const recent = list.slice(-3);
  const recentAvg = recent.reduce((s, x) => s + x.late, 0) / recent.length;
  return {
    hasHistory: true, count: list.length, lateRate, avgLate,
    maxLate: Math.max(...list.map(x => x.late)),
    trend: list.length >= 4 ? Math.round((recentAvg - overall) * 10) / 10 : 0,
  };
};

// 2. Open invoices grouped by client
const clients = {};
for (const inv of invoices) {
  if (CLOSED.includes(String(inv['Status'] || '').toLowerCase().trim())) continue;
  const due = parse(inv['Due Date']);
  const clientId = String(inv['Client ID'] || '').trim();
  if (!due || !clientId) continue;
  const c = clients[clientId] || (clients[clientId] = {
    clientId, clientName: inv['Client Name'], clientEmail: String(inv['Client Email'] || '').trim(),
    invoices: [], newReply: null,
  });
  c.invoices.push({
    invoiceId: String(inv['Invoice ID']),
    amount: parseFloat(String(inv['Amount'] || 0).replace(/[^0-9.\-]/g, '')) || 0,
    currency: inv['Currency'] || cfg.defaultCurrency,
    dueDate: iso(due),
    daysOverdue: Math.round((today - due) / DAY),
    lastStage: String(inv['Last Reminder Stage'] || '').toLowerCase().trim(),
    lastDate: inv['Last Reminder Date'] || '',
  });
}

// 3. Newest unprocessed reply per client
const processed = new Set(responses.map(r => String(r['Response ID'])));
const byEmail = {};
for (const c of Object.values(clients)) if (c.clientEmail) byEmail[c.clientEmail.toLowerCase()] = c;
for (const m of mails) {
  const from = String((m.from && m.from.value && m.from.value[0] && m.from.value[0].address) || '').toLowerCase();
  const c = byEmail[from];
  if (!c || processed.has(String(m.id))) continue;
  if (c.newReply && new Date(c.newReply.receivedAt) >= new Date(m.date)) continue;
  c.newReply = { messageId: m.id, threadId: m.threadId, subject: m.subject || '', receivedAt: m.date, text: String(m.text || m.snippet || '') };
}

// 4. Promise-keeping record
const broken = {};
for (const r of responses) {
  if (r['Intent'] === 'promise_to_pay' && r['Status'] === 'Broken') {
    const id = String(r['Client ID']); broken[id] = (broken[id] || 0) + 1;
  }
}

return Object.values(clients).map(c => ({
  json: { ...c, profile: profileOf(c.clientId), brokenPromises: broken[c.clientId] || 0, hasNewReply: !!c.newReply },
}));

