// Turn the AI classification into a logged client response with a clear status
const cfg = $('Set Dunning Rules1').first().json;
const todayISO = $today.toISODate();
const OPEN_INTENTS = ['promise_to_pay', 'dispute', 'payment_claimed', 'extension_request'];
const out = [];

$input.all().forEach((item, i) => {
  const c = $('Has New Reply?').itemMatching(i).json;
  let f = item.json.message && item.json.message.content;
  if (typeof f === 'string') { try { f = JSON.parse(f); } catch (e) { f = null; } }
  if (item.json.error || !f) f = { intent: 'unclear', summary: 'Reply could not be classified automatically', confidence: 0 };

  let intent = String(f.intent || 'other');
  const conf = Number(f.confidence);
  if (!isNaN(conf) && conf < (Number(cfg.minIntentConfidence) || 0.6)) intent = 'unclear';

  let promisedDate = /^\d{4}-\d{2}-\d{2}$/.test(String(f.promisedDate || '')) ? f.promisedDate : '';
  if (intent === 'promise_to_pay') {
    if (!promisedDate || promisedDate < todayISO) promisedDate = $today.plus({ days: Number(cfg.ptpDefaultDays) || 7 }).toISODate();
    // A "promise" far in the future is really an extension request
    if (promisedDate > $today.plus({ days: Number(cfg.maxPromiseDays) || 45 }).toISODate()) intent = 'extension_request';
  }

  const refs = Array.isArray(f.invoiceRefs) ? f.invoiceRefs.map(String) : [];
  const valid = new Set(c.invoices.map(v => v.invoiceId));
  const invoiceRefs = refs.filter(r => valid.has(r)).join(', ');
  const total = c.invoices.reduce((s, v) => s + v.amount, 0);
  const LABEL = {
    dispute: ':warning: *Dispute raised*', payment_claimed: ':moneybag: *Client says it is already paid, please verify*',
    extension_request: ':hourglass: *Extension / payment plan requested*', unclear: ':mag: *Reply needs a human read*',
  };

  out.push({
    json: {
      responseId: String(c.newReply.messageId),
      threadId: c.newReply.threadId,
      clientId: c.clientId,
      clientName: c.clientName,
      clientEmail: c.clientEmail,
      receivedAt: c.newReply.receivedAt,
      intent,
      promisedDate: intent === 'promise_to_pay' ? promisedDate : '',
      invoiceRefs,
      summary: String(f.summary || ''),
      confidence: isNaN(conf) ? '' : conf,
      status: OPEN_INTENTS.includes(intent) ? 'Open' : 'Logged',
      loggedOn: todayISO,
      alertText: `${LABEL[intent] || '*Client reply*'} from ${c.clientName}\n` +
        `${c.invoices.length} open invoice(s), ${c.invoices[0].currency} ${total.toLocaleString('en-US')}` +
        (invoiceRefs ? ` (mentions ${invoiceRefs})` : '') +
        `\n> ${String(f.summary || '').slice(0, 280)}\nDunning is paused for this client until someone updates the Client Responses tab.`,
    },
    pairedItem: { item: i },
  });
});
return out;

// Score every open invoice, apply holds (promises, disputes, payment claims),
// detect broken promises and pick ONE consolidated action per client.
const cfg = $('Set Dunning Rules1').first().json;
const clients = $input.all().map(i => i.json);
const DAY = 86400000;
const today = new Date(); today.setHours(0, 0, 0, 0);
const todayISO = today.toISOString().slice(0, 10);
const parse = v => { if (!v) return null; const d = new Date(v); if (isNaN(d)) return null; d.setHours(0, 0, 0, 0); return d; };
const daysSince = v => { const d = parse(v); return d ? Math.round((today - d) / DAY) : Infinity; };
const addDays = (isoStr, n) => { const d = parse(isoStr); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
const ORDER = { friendly: 1, firm: 2, call: 3, final: 4 };

// Responses: sheet history + anything classified earlier in this run
const resp = {};
for (const r of $('Read Client Responses').all().map(i => i.json).filter(r => r['Response ID'])) {
  resp[r['Response ID']] = {
    id: String(r['Response ID']), clientId: String(r['Client ID']), intent: r['Intent'], status: r['Status'],
    promisedDate: r['Promised Date'] || '', receivedAt: r['Received On'] || '', refs: String(r['Invoice Refs'] || ''),
  };
}
let todays = [];
try { todays = $('Attach Intent to Client').all().map(i => i.json); } catch (e) { /* no replies today */ }
for (const t of todays) {
  resp[t.responseId] = { id: t.responseId, clientId: t.clientId, intent: t.intent, status: t.status,
    promisedDate: t.promisedDate, receivedAt: t.receivedAt, refs: t.invoiceRefs };
}
const respByClient = {};
for (const r of Object.values(resp)) (respByClient[r.clientId] = respByClient[r.clientId] || []).push(r);

const out = [];
for (const c of clients) {
  const p = c.profile;
  const rs = respByClient[c.clientId] || [];
  const brokenIds = [];
  let brokenTotal = c.brokenPromises;

  // Holds: map invoiceId -> reason ('*' = whole client)
  const holds = {};
  const hold = (refs, reason) => {
    const list = String(refs || '').split(',').map(s => s.trim()).filter(Boolean);
    if (!list.length) holds['*'] = holds['*'] || reason; else for (const id of list) holds[id] = holds[id] || reason;
  };
  for (const r of rs) {
    if (r.status !== 'Open') continue;
    if (r.intent === 'dispute') hold(r.refs, 'Dispute open');
    if (r.intent === 'payment_claimed' && daysSince(r.receivedAt) <= cfg.paymentClaimHoldDays) hold(r.refs, 'Payment claimed, awaiting verification');
    if (r.intent === 'extension_request' && daysSince(r.receivedAt) <= cfg.extensionHoldDays) hold(r.refs, 'Extension requested, awaiting decision');
    if (r.intent === 'promise_to_pay' && r.promisedDate) {
      if (todayISO <= addDays(r.promisedDate, cfg.ptpGraceDays)) hold(r.refs, `Promised to pay by ${r.promisedDate}`);
      else { brokenIds.push(r.id); brokenTotal++; }
    }
  }

  const overdueTotal = c.invoices.filter(v => v.daysOverdue > 0).reduce((s, v) => s + v.amount, 0);
  const expectedDelay = Math.round(p.avgLate);
  const detail = [];
  const actionable = [];

  for (const v of c.invoices) {
    const od = v.daysOverdue;
    // Risk score 0-100
    const score = Math.min(100, Math.round(
      p.lateRate * 30 +
      (Math.min(p.avgLate, 45) / 45) * 20 +
      (Math.min(p.maxLate, 90) / 90) * 8 +
      (Math.min(Math.max(od, 0), 30) / 30) * 16 +
      Math.min(overdueTotal / (Number(cfg.largeExposureAmount) || 10000), 1) * 10 +
      (Math.min(Math.max(p.trend, 0), 15) / 15) * 8 +
      Math.min(brokenTotal, 2) * 8
    ));
    const band = score >= cfg.highRiskScore ? 'high' : score >= cfg.mediumRiskScore ? 'medium' : 'low';
    const predicted = new Date(Math.max(parse(v.dueDate).getTime() + expectedDelay * DAY, today.getTime() + DAY));
    const heldReason = holds[v.invoiceId] || holds['*'] || '';

    let stage = null, reason = '';
    if (od >= cfg.finalNoticeAfterDays && ['call', 'final'].includes(v.lastStage)) { stage = 'final'; reason = `${od} days overdue after a call attempt`; }
    else if (od >= cfg.callAfterDaysOverdue) { stage = 'call'; reason = `${od} days overdue`; }
    else if (brokenTotal >= 2 && od > cfg.friendlyMaxDaysOverdue) { stage = 'call'; reason = `${brokenTotal} broken payment promises`; }
    else if (band === 'high' && od > cfg.friendlyMaxDaysOverdue) { stage = 'call'; reason = `High-risk client, ${od} days overdue`; }
    else if (brokenIds.length && od > 0) { stage = 'firm'; reason = 'Promised payment date has passed'; }
    else if (od > cfg.friendlyMaxDaysOverdue) { stage = 'firm'; reason = `${od} days overdue`; }
    else if (band !== 'low' && od > 0) { stage = 'firm'; reason = `${band} risk client, already overdue`; }
    else if (od > 0) { stage = 'friendly'; reason = 'Recently overdue, reliable payer'; }
    else if (band !== 'low' && od >= -cfg.preDueNudgeDays) { stage = 'friendly'; reason = `Predicted to pay late, due in ${-od} day(s)`; }

    // Never soften, respect cooldowns
    if (stage && ORDER[v.lastStage] && ORDER[stage] < ORDER[v.lastStage]) stage = v.lastStage;
    const since = daysSince(v.lastDate);
    let skip = '';
    if (heldReason) skip = heldReason;
    else if (stage && since < cfg.minDaysBetweenReminders) skip = 'Cooldown';
    else if (stage === 'call' && v.lastStage === 'call' && since < cfg.daysBetweenCallTasks) skip = 'Call task already open';
    else if (stage === 'final' && v.lastStage === 'final' && since < cfg.daysBetweenFinalNotices) skip = 'Final notice recently sent';

    const row = { ...v, riskScore: score, riskBand: band, predictedPayDate: predicted.toISOString().slice(0, 10),
      stage: stage && !skip ? stage : 'none', reason, heldReason, skipReason: stage ? skip : '' };
    detail.push(row);
    if (row.stage !== 'none') actionable.push(row);
  }

  const top = actionable.reduce((m, v) => (ORDER[v.stage] > ORDER[m] ? v.stage : m), 'friendly');
  const riskScore = Math.max(0, ...detail.map(v => v.riskScore));
  const riskBand = riskScore >= cfg.highRiskScore ? 'high' : riskScore >= cfg.mediumRiskScore ? 'medium' : 'low';
  const cur = c.invoices[0].currency;
  out.push({
    json: {
      clientId: c.clientId, clientName: c.clientName, clientEmail: c.clientEmail, currency: cur,
      stage: actionable.length && c.clientEmail ? top : 'none',
      reason: [...new Set(actionable.filter(v => v.stage === top).map(v => v.reason))].join('; '),
      invoices: actionable,
      invoiceIds: actionable.map(v => v.invoiceId).join(', '),
      invoiceList: actionable.map(v => `- ${v.invoiceId}: ${v.currency} ${v.amount.toLocaleString('en-US')} due ${v.dueDate} (${v.daysOverdue > 0 ? v.daysOverdue + ' days overdue' : 'due in ' + -v.daysOverdue + ' day(s)'})`).join('\n'),
      totalDue: Math.round(actionable.reduce((s, v) => s + v.amount, 0) * 100) / 100,
      maxDaysOverdue: Math.max(0, ...actionable.map(v => v.daysOverdue)),
      overdueTotal: Math.round(overdueTotal * 100) / 100,
      riskScore, riskBand,
      lateRatePct: Math.round(p.lateRate * 100),
      avgDaysLate: expectedDelay,
      paidInvoicesOnRecord: p.count,
      trendLabel: p.trend > 2 ? `worsening (+${p.trend} days recently)` : p.trend < -2 ? `improving (${p.trend} days)` : 'stable',
      brokenPromises: brokenTotal,
      brokenPromiseIds: brokenIds,
      creditHold: riskBand === 'high' && overdueTotal >= cfg.creditHoldExposure,
      allInvoices: detail,
    },
  });
}
out.sort((a, b) => b.json.riskScore - a.json.riskScore);
return out;

// Mark promises whose date (plus grace) has passed as Broken
const rows = [];
for (const c of $input.all().map(i => i.json)) {
  for (const id of c.brokenPromiseIds || []) rows.push({ json: { responseId: id, clientName: c.clientName } });
}
return rows;

// Daily AR digest for Slack: aging, holds, actions, forecast, credit holds
const cfg = $('Set Dunning Rules1').first().json;
const clients = $input.all().map(i => i.json);
let todays = [];
try { todays = $('Attach Intent to Client').all().map(i => i.json); } catch (e) {}

const add = (m, cur, v) => { m[cur] = (m[cur] || 0) + v; };
const fmt = m => Object.entries(m).map(([c, v]) => `${c} ${Math.round(v).toLocaleString('en-US')}`).join(' · ') || '0';
const aging = { 'Not due': {}, '1-30': {}, '31-60': {}, '61-90': {}, '90+': {} };
const forecast = { '7 days': {}, '30 days': {} };
const holds = {};
const stages = { friendly: 0, firm: 0, call: 0, final: 0 };
const in7 = $today.plus({ days: 7 }).toISODate(), in30 = $today.plus({ days: 30 }).toISODate();
let broken = 0;

for (const c of clients) {
  if (stages[c.stage] !== undefined) stages[c.stage]++;
  broken += (c.brokenPromiseIds || []).length;
  for (const v of c.allInvoices) {
    const od = v.daysOverdue;
    const b = od <= 0 ? 'Not due' : od <= 30 ? '1-30' : od <= 60 ? '31-60' : od <= 90 ? '61-90' : '90+';
    add(aging[b], v.currency, v.amount);
    if (v.predictedPayDate <= in7) add(forecast['7 days'], v.currency, v.amount);
    if (v.predictedPayDate <= in30) add(forecast['30 days'], v.currency, v.amount);
    if (v.heldReason) holds[v.heldReason.split(' by ')[0]] = (holds[v.heldReason.split(' by ')[0]] || 0) + 1;
  }
}
const risky = clients.filter(c => c.overdueTotal > 0).slice(0, 5)
  .map(c => `• ${c.clientName}: ${c.currency} ${c.overdueTotal.toLocaleString('en-US')} overdue, risk ${c.riskScore}/100, ${c.trendLabel}${c.creditHold ? ' :no_entry: *credit hold recommended*' : ''}`);
const intents = {};
for (const t of todays) intents[t.intent] = (intents[t.intent] || 0) + 1;

const text = [
  `:bar_chart: *AR digest - ${$today.toFormat('ccc, d LLL yyyy')}*`,
  `*Aging:* ${Object.entries(aging).map(([k, m]) => `${k}: ${fmt(m)}`).join('  |  ')}`,
  `*Expected in (based on each client's payment habits):* next 7 days ${fmt(forecast['7 days'])}, next 30 days ${fmt(forecast['30 days'])}`,
  `*Actions today:* ${stages.friendly} friendly, ${stages.firm} firm, ${stages.call} call task(s), ${stages.final} final notice(s) pending approval`,
  `*Client replies today:* ${Object.entries(intents).map(([k, v]) => `${v} ${k.replace(/_/g, ' ')}`).join(', ') || 'none'}`,
  `*On hold:* ${Object.entries(holds).map(([k, v]) => `${v} invoice(s) - ${k}`).join(', ') || 'none'}`,
  broken ? `:rotating_light: *${broken} promise(s) to pay were broken* and have been escalated.` : '',
  risky.length ? `*Top overdue clients:*\n${risky.join('\n')}` : '',
].filter(Boolean).join('\n');
return [{ json: { text } }];

// One approval request for all final notices in this run
const list = $input.all().map(i => i.json);
const lines = list.map(c => `• *${c.clientName}* - ${c.currency} ${c.totalDue.toLocaleString('en-US')}, ${c.maxDaysOverdue} days overdue, risk ${c.riskScore}/100, ${c.brokenPromises} broken promise(s)`);
return [{ json: { count: list.length, lines: lines.join('\n'), clients: list } }];

// Approved -> final notice email. Declined or timed out -> fall back to a call task.
const approved = !!($json.data && $json.data.approved === true);
const clients = $('Bundle Final Notices').first().json.clients;
return clients.map(c => ({
  json: {
    ...c,
    stage: approved ? 'final' : 'call',
    reason: approved ? c.reason : `${c.reason} (final notice not approved, call instead)`,
    finalApproved: approved,
  },
  pairedItem: { item: 0 },
}));

