// One log row per invoice actioned. Failed sends do not advance the stage.
const todayISO = $today.toISODate();
const now = $now.toISO();
const clientFor = i => {
  for (const n of ['Unpack Final Notice Decisions', 'Decide Next Action']) {
    try { const j = $(n).itemMatching(i).json; if (j && j.clientId) return j; } catch (e) {}
  }
  return null;
};
const CHANNEL = { friendly: 'Email', firm: 'Email', final: 'Email (final notice)', call: 'Call task + Slack' };
const out = [];

$input.all().forEach((item, i) => {
  const c = clientFor(i);
  if (!c) return;
  const ok = !item.json.error;
  for (const v of c.invoices) {
    out.push({
      json: {
        invoiceId: v.invoiceId,
        clientId: c.clientId,
        clientName: c.clientName,
        stage: ok ? c.stage : v.lastStage,
        reminderDate: ok ? todayISO : v.lastDate,
        riskScore: v.riskScore,
        predictedPayDate: v.predictedPayDate,
        creditHold: c.creditHold ? 'Yes' : 'No',
        dunningStatus: ok ? `${c.stage} sent ${todayISO}` : `Send failed ${todayISO}: ${String(item.json.error.message || item.json.error).slice(0, 120)}`,
        logId: `${v.invoiceId}-${c.stage}-${now}`,
        loggedAt: now,
        channel: CHANNEL[c.stage] || c.stage,
        outcome: ok ? 'Done' : 'Failed',
        detail: c.reason,
      },
      pairedItem: { item: i },
    });
  }
});
return out;

